another way is to add a parameter: `ignoreLibraryName`, `false` by default, for `commonjs2` it will be true:

```
case "commonjs2": {
  const AssignLibraryPlugin = require("./AssignLibraryPlugin");
  new AssignLibraryPlugin({
    type,
    prefix: ["module", "exports"],
    declare: false,
    ignoreLibraryName: true,
    unnamed: "assign"
  }).apply(compiler);
  break;
}
```
